   772  static void _parse_prop(struct vcardparser_state *state)
   773  {
   774      int r = _parse_prop_name(state);
   775      if (r) {
   776          if (r == PE_PROP_MULTIGROUP) {
   777              vcardproperty_kind prop_kind = vcardproperty_isa(state->prop);
   778
   779              _parse_error(state,
   780                           VCARD_XLICERRORTYPE_PROPERTYPARSEERROR,
   781                           "%s '%s.%s'. Removing entire property",
   782                           vcardparser_errstr(r),
   783                           vcardproperty_get_group(state->prop),
   784                           vcardproperty_kind_to_string(prop_kind));
   785              _parse_eatline(state);
   786          } else if (r == PE_NAME_INVALID) {
   787              _parse_error(state,
   788                           VCARD_XLICERRORTYPE_PROPERTYPARSEERROR,
   789                           "%s '%s'. Removing entire property",
   790                           vcardparser_errstr(r), buf_cstring(&state->buf));
   791              _parse_eatline(state);
   792          } else {
   793              _parse_error(state,
   794                           VCARD_XLICERRORTYPE_PROPERTYPARSEERROR,
   795                           "%s '%s'. Ignoring property",
   796                           vcardparser_errstr(r), buf_cstring(&state->buf));
   797          }
   798          return;
   799      }
   800
   801      if (*state->p == ';') {
   802          r = _parse_prop_params(state);
   803          if (r) {
   804              /* errors handled in _parse_prop_params() */
   805              return;
   806          }
   807      }
   808
   809      INC(1); /* skip ':' */
   810      r = _parse_prop_value(state);
   811      if (r) {
   812          vcardproperty_kind prop_kind = vcardproperty_isa(state->prop);
   813          const char *group = vcardproperty_get_group(state->prop);
   814
   815          if (r == PE_VALUE_INVALID) {
   816              _parse_error(state,
   817                           VCARD_XLICERRORTYPE_VALUEPARSEERROR,
   818                           "Error parsing '%s' as %s value in %s%s%s property."
   819                           " Removing entire property",
   820                           buf_cstring(&state->buf),
   821                           vcardvalue_kind_to_string(state->value_kind),
   822                           group ? group : "", group ? "." : "",
   823                           vcardproperty_kind_to_string(prop_kind));
   824          } else {
   825              _parse_error(state,
   826                           VCARD_XLICERRORTYPE_VALUEPARSEERROR,
   827                           "%s in %s%s%s property. Removing entire property",
   828                           vcardparser_errstr(r),
   829                           group ? group : "", group ? "." : "",
   830                           vcardproperty_kind_to_string(prop_kind));
   831          }
   832      }
   833  }
